-- Title: catalog resolve sellable products by ids
-- Kind: patch
-- Intent: catalog_sellable_lookup_by_ids
-- Context: TH-05 EP-01 — Sales draft save/restore needs a real lookup-by-id so a
-- Touches: resolve_sellable_products
-- Safety: idempotent ; low (new function only)
-- Depends on: 20260830002_catalog_sales_sellable_lookup_group_a
-- Promoted from _drafts/016_catalog_sellable_lookup_by_ids.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function catalog.resolve_sellable_products(
  p_tenant_id uuid,
  p_store_id uuid,
  p_product_ids uuid[]
)
returns jsonb
language plpgsql
stable
security definer
set search_path = catalog, iam, inventory, pg_temp
as $$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not exists (
    select 1
    from iam.memberships membership
    where membership.tenant_id = p_tenant_id
      and membership.user_id = auth.uid()
  ) then
    raise exception 'tenant access denied';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  if not iam.can_access_store(p_tenant_id, p_store_id, auth.uid()) then
    raise exception 'store access denied';
  end if;

  return (
    with requested as (
      select distinct requested_id
      from unnest(coalesce(p_product_ids, array[]::uuid[])) as requested_id
      where requested_id is not null
    ),
    resolved as (
      select
        r.requested_id,
        p.id,
        p.tenant_id,
        p.name,
        p.trade_name,
        p.sku,
        p.barcode,
        p.is_ready_to_sell,
        p.business_status
      from requested r
      left join catalog.products p
        on p.id = r.requested_id
       and p.tenant_id = p_tenant_id
    )
    select jsonb_build_object(
      'items', coalesce(
        jsonb_agg(
          case
            when resolved.id is null then jsonb_build_object(
              'product_id', resolved.requested_id,
              'resolution', 'not_found',
              'product', null,
              'sku', null,
              'display_name', null,
              'block_reason', null
            )
            when resolved.business_status
                 <> 'active'::catalog.product_business_status
              or resolved.is_ready_to_sell = false
              or product_price.currency is null
            then jsonb_build_object(
              'product_id', resolved.id,
              'resolution', 'not_sellable',
              'product', null,
              'sku', resolved.sku,
              'display_name', resolved.name,
              'block_reason', case
                when resolved.business_status
                     <> 'active'::catalog.product_business_status
                  then 'product_inactive'
                when resolved.is_ready_to_sell = false
                  then 'product_not_ready_to_sell'
                else 'no_active_price_band'
              end
            )
            else jsonb_build_object(
              'product_id', resolved.id,
              'resolution', 'sellable',
              'sku', resolved.sku,
              'display_name', resolved.name,
              'block_reason', null,
              'product', jsonb_build_object(
                'product_id', resolved.id,
                'sku', resolved.sku,
                'display_name', resolved.name,
                'trade_name', resolved.trade_name,
                'is_sellable', resolved.is_ready_to_sell,
                'block_reason', null,
                'currency_code', product_price.currency,
                'list_price_minor', product_price.list_price_minor,
                'floor_price_minor', product_price.floor_price_minor,
                'available_stock_micros', (
                  select (trunc(coalesce(sr.available, 0)) * 1000000)::bigint
                  from inventory._product_stock_rows(p_tenant_id, array[resolved.id]) sr
                  limit 1
                ),
                'units', units.units
              )
            )
          end
          order by resolved.requested_id asc
        ),
        '[]'::jsonb
      )
    )
    from resolved
    left join lateral (
      select bp.currency,
        pb.list_price_after_vat::bigint as list_price_minor,
        pb.floor_price_after_vat::bigint as floor_price_minor
      from catalog.product_units pu
      join catalog.product_base_price_profiles bp
        on bp.product_id = resolved.id
       and bp.tenant_id = resolved.tenant_id
      join catalog.product_unit_price_bands pb
        on pb.product_id = resolved.id
       and pb.product_unit_id = pu.id
       and pb.tenant_id = resolved.tenant_id
       and pb.status = 'active'
       and pb.effective_from <= now()
       and (pb.effective_to is null or pb.effective_to > now())
      where pu.tenant_id = p_tenant_id
        and pu.product_id = resolved.id
        and pu.is_active = true
        and pb.list_price_after_vat is not null
        and trunc(pb.list_price_after_vat) = pb.list_price_after_vat
        and (pb.floor_price_after_vat is null
          or trunc(pb.floor_price_after_vat) = pb.floor_price_after_vat)
      order by pu.is_base_unit desc, pu.unit_name asc, pu.id asc
      limit 1
    ) product_price on true
    left join lateral (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'product_unit_id', pu.id,
            'unit_code', pu.unit_name,
            'unit_name', pu.unit_name,
            'barcode', resolved.barcode,
            'is_default', pu.is_base_unit,
            'is_active', pu.is_active,
            'is_sellable', resolved.is_ready_to_sell and pu.is_active,
            'block_reason', null,
            'list_price_minor', pb.list_price_after_vat::bigint,
            'floor_price_minor', pb.floor_price_after_vat::bigint,
            'available_stock_micros', case
              when coalesce(pu.conversion_rate_to_base, 0) <= 0 then null
              else (
                trunc(coalesce(sr.available, 0) / pu.conversion_rate_to_base)
                * 1000000
              )::bigint
            end
          )
          order by pu.is_base_unit desc, pu.unit_name asc, pu.id asc
        ),
        '[]'::jsonb
      ) as units
      from catalog.product_units pu
      join catalog.product_unit_price_bands pb
        on pb.product_id = resolved.id
       and pb.product_unit_id = pu.id
       and pb.tenant_id = resolved.tenant_id
       and pb.status = 'active'
       and pb.effective_from <= now()
       and (pb.effective_to is null or pb.effective_to > now())
      left join inventory._product_stock_rows(p_tenant_id, array[resolved.id]) sr
        on sr.product_id = resolved.id
      where pu.tenant_id = p_tenant_id
        and pu.product_id = resolved.id
        and pu.is_active = true
        and pb.list_price_after_vat is not null
        and trunc(pb.list_price_after_vat) = pb.list_price_after_vat
        and (pb.floor_price_after_vat is null
          or trunc(pb.floor_price_after_vat) = pb.floor_price_after_vat)
    ) units on true
  );
end;
$$;

revoke all on function catalog.resolve_sellable_products(uuid, uuid, uuid[])
  from public, anon;
grant execute on function catalog.resolve_sellable_products(uuid, uuid, uuid[])
  to authenticated, service_role;
